-- create-table /TRBASE/AUDIT_LOG
CREATE TABLE "/TRBASE/AUDIT_LOG" (
  "/RT/TENANT" TEXT NOT NULL,
  "LOG_ID" TEXT NOT NULL,
  "TEXT" TEXT NOT NULL,
  CONSTRAINT "/TRBASE/AUDIT_LOG#PK" PRIMARY KEY ("/RT/TENANT", "LOG_ID"),
  CONSTRAINT "/TRBASE/AUDIT_LOG#FK#/RT/TENANT" FOREIGN KEY ("/RT/TENANT") REFERENCES "/RT/TENANTS" ("TENANT"),
  CONSTRAINT "/TRBASE/AUDIT_LOG#CK#/RT/TENANT" CHECK ("/RT/TENANT" IS NULL OR (length("/RT/TENANT") <= 16)),
  CONSTRAINT "/TRBASE/AUDIT_LOG#CK#LOG_ID" CHECK ("LOG_ID" IS NULL OR ("LOG_ID" GLOB '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]-[0-9a-f][0-9a-f][0-9a-f][0-9a-f]-[0-9a-f][0-9a-f][0-9a-f][0-9a-f]-[0-9a-f][0-9a-f][0-9a-f][0-9a-f]-[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]'))
) STRICT;

-- create-table /TRDEMOFIN/BANK_ACCOUNTS
CREATE TABLE "/TRDEMOFIN/BANK_ACCOUNTS" (
  "/RT/TENANT" TEXT NOT NULL,
  "COMPANY_ID" TEXT NOT NULL,
  "ACCOUNT_NO" INTEGER NOT NULL,
  "IBAN" TEXT NOT NULL,
  "BALANCE" INTEGER NOT NULL DEFAULT 0,
  "OPENED_AT" TEXT,
  CONSTRAINT "/TRDEMOFIN/BANK_ACCOUNTS#PK" PRIMARY KEY ("/RT/TENANT", "COMPANY_ID", "ACCOUNT_NO"),
  CONSTRAINT "/TRDEMOFIN/BANK_ACCOUNTS#FK#/RT/TENANT" FOREIGN KEY ("/RT/TENANT") REFERENCES "/RT/TENANTS" ("TENANT"),
  CONSTRAINT "/TRDEMOFIN/BANK_ACCOUNTS#FK#COMPANY" FOREIGN KEY ("/RT/TENANT", "COMPANY_ID") REFERENCES "/TRDEMOFIN/COMPANIES" ("/RT/TENANT", "COMPANY_ID"),
  CONSTRAINT "/TRDEMOFIN/BANK_ACCOUNTS#CK#/RT/TENANT" CHECK ("/RT/TENANT" IS NULL OR (length("/RT/TENANT") <= 16)),
  CONSTRAINT "/TRDEMOFIN/BANK_ACCOUNTS#CK#COMPANY_ID" CHECK ("COMPANY_ID" IS NULL OR (length("COMPANY_ID") <= 10)),
  CONSTRAINT "/TRDEMOFIN/BANK_ACCOUNTS#CK#ACCOUNT_NO" CHECK ("ACCOUNT_NO" IS NULL OR ("ACCOUNT_NO" BETWEEN -2147483648 AND 2147483647)),
  CONSTRAINT "/TRDEMOFIN/BANK_ACCOUNTS#CK#IBAN" CHECK ("IBAN" IS NULL OR (length("IBAN") <= 34)),
  CONSTRAINT "/TRDEMOFIN/BANK_ACCOUNTS#CK#BALANCE" CHECK ("BALANCE" IS NULL OR ("BALANCE" BETWEEN -999999999999999 AND 999999999999999)),
  CONSTRAINT "/TRDEMOFIN/BANK_ACCOUNTS#CK#OPENED_AT" CHECK ("OPENED_AT" IS NULL OR ("OPENED_AT" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z' AND strftime('%Y-%m-%dT%H:%M:%S', substr("OPENED_AT", 1, 19)) IS substr("OPENED_AT", 1, 19)))
) STRICT;

-- create-table /TRDEMOFIN/COMPANIES
CREATE TABLE "/TRDEMOFIN/COMPANIES" (
  "/RT/TENANT" TEXT NOT NULL,
  "COMPANY_ID" TEXT NOT NULL,
  "NAME" TEXT NOT NULL,
  "STREET" TEXT,
  "POSTAL_CODE" TEXT,
  "CITY" TEXT,
  "COUNTRY" TEXT,
  "/TRDEMOOTTO/PICKUP_POINT" TEXT,
  "STATUS" TEXT NOT NULL DEFAULT 'ACTIVE',
  "CAPITAL" INTEGER,
  "FOUNDED_ON" TEXT,
  "CREATED_BY" TEXT,
  "CREATED_AT" TEXT,
  "CHANGED_BY" TEXT,
  "CHANGED_AT" TEXT,
  "/TRDEMOOTTO/OTTO_ID" TEXT,
  CONSTRAINT "/TRDEMOFIN/COMPANIES#PK" PRIMARY KEY ("/RT/TENANT", "COMPANY_ID"),
  CONSTRAINT "/TRDEMOFIN/COMPANIES#FK#/RT/TENANT" FOREIGN KEY ("/RT/TENANT") REFERENCES "/RT/TENANTS" ("TENANT"),
  CONSTRAINT "/TRDEMOFIN/COMPANIES#FK#COUNTRY" FOREIGN KEY ("COUNTRY") REFERENCES "/TRDEMOFIN/COUNTRIES" ("COUNTRY_CODE"),
  CONSTRAINT "/TRDEMOFIN/COMPANIES#CK#/RT/TENANT" CHECK ("/RT/TENANT" IS NULL OR (length("/RT/TENANT") <= 16)),
  CONSTRAINT "/TRDEMOFIN/COMPANIES#CK#COMPANY_ID" CHECK ("COMPANY_ID" IS NULL OR (length("COMPANY_ID") <= 10)),
  CONSTRAINT "/TRDEMOFIN/COMPANIES#CK#NAME" CHECK ("NAME" IS NULL OR (length("NAME") <= 80)),
  CONSTRAINT "/TRDEMOFIN/COMPANIES#CK#STREET" CHECK ("STREET" IS NULL OR (length("STREET") <= 60)),
  CONSTRAINT "/TRDEMOFIN/COMPANIES#CK#POSTAL_CODE" CHECK ("POSTAL_CODE" IS NULL OR (length("POSTAL_CODE") <= 10)),
  CONSTRAINT "/TRDEMOFIN/COMPANIES#CK#CITY" CHECK ("CITY" IS NULL OR (length("CITY") <= 40)),
  CONSTRAINT "/TRDEMOFIN/COMPANIES#CK#COUNTRY" CHECK ("COUNTRY" IS NULL OR (length("COUNTRY") <= 2)),
  CONSTRAINT "/TRDEMOFIN/COMPANIES#CK#/TRDEMOOTTO/PICKUP_POINT" CHECK ("/TRDEMOOTTO/PICKUP_POINT" IS NULL OR (length("/TRDEMOOTTO/PICKUP_POINT") <= 20)),
  CONSTRAINT "/TRDEMOFIN/COMPANIES#CK#STATUS" CHECK ("STATUS" IS NULL OR (length("STATUS") <= 10 AND "STATUS" IN ('ACTIVE', 'BLOCKED', 'CLOSED'))),
  CONSTRAINT "/TRDEMOFIN/COMPANIES#CK#CAPITAL" CHECK ("CAPITAL" IS NULL OR ("CAPITAL" BETWEEN -999999999999999 AND 999999999999999)),
  CONSTRAINT "/TRDEMOFIN/COMPANIES#CK#FOUNDED_ON" CHECK ("FOUNDED_ON" IS NULL OR ("FOUNDED_ON" IS date("FOUNDED_ON"))),
  CONSTRAINT "/TRDEMOFIN/COMPANIES#CK#CREATED_BY" CHECK ("CREATED_BY" IS NULL OR (length("CREATED_BY") <= 80)),
  CONSTRAINT "/TRDEMOFIN/COMPANIES#CK#CREATED_AT" CHECK ("CREATED_AT" IS NULL OR ("CREATED_AT" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z' AND strftime('%Y-%m-%dT%H:%M:%S', substr("CREATED_AT", 1, 19)) IS substr("CREATED_AT", 1, 19))),
  CONSTRAINT "/TRDEMOFIN/COMPANIES#CK#CHANGED_BY" CHECK ("CHANGED_BY" IS NULL OR (length("CHANGED_BY") <= 80)),
  CONSTRAINT "/TRDEMOFIN/COMPANIES#CK#CHANGED_AT" CHECK ("CHANGED_AT" IS NULL OR ("CHANGED_AT" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z' AND strftime('%Y-%m-%dT%H:%M:%S', substr("CHANGED_AT", 1, 19)) IS substr("CHANGED_AT", 1, 19))),
  CONSTRAINT "/TRDEMOFIN/COMPANIES#CK#/TRDEMOOTTO/OTTO_ID" CHECK ("/TRDEMOOTTO/OTTO_ID" IS NULL OR (length("/TRDEMOOTTO/OTTO_ID") <= 20))
) STRICT;

